import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../models/station.dart';
import '../../services/app_state.dart';
class ReservationScreen extends StatefulWidget { final Station station; const ReservationScreen({super.key,required this.station}); @override State<ReservationScreen> createState()=>_ReservationScreenState(); }
class _ReservationScreenState extends State<ReservationScreen>{ DateTime date=DateTime.now(); TimeOfDay time=TimeOfDay.now(); int minutes=60;
 Future<void> pickDate() async {final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:60)),initialDate:date);if(d!=null)setState(()=>date=d);}
 Future<void> pickTime() async {final t=await showTimePicker(context:context,initialTime:time);if(t!=null)setState(()=>time=t);}
 @override Widget build(BuildContext context){final state=context.watch<AppState>(); final courtesy=!state.courtesyUsed; final gross=widget.station.pricePerHour*(minutes/60); return Scaffold(appBar:AppBar(title:const Text('Nova reserva')),body:ListView(padding:const EdgeInsets.all(20),children:[Text(widget.station.name,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Text(widget.station.address),const SizedBox(height:24),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.calendar_month),title:const Text('Data'),subtitle:Text('${date.day.toString().padLeft(2,'0')}/${date.month.toString().padLeft(2,'0')}/${date.year}'),trailing:TextButton(onPressed:pickDate,child:const Text('Alterar'))),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.schedule),title:const Text('Horário'),subtitle:Text(time.format(context)),trailing:TextButton(onPressed:pickTime,child:const Text('Alterar'))),const SizedBox(height:12),DropdownButtonFormField<int>(initialValue:minutes,decoration:const InputDecoration(labelText:'Duração'),items:const[60,90,120].map((m)=>DropdownMenuItem(value:m,child:Text('$m minutos'))).toList(),onChanged:(v)=>setState(()=>minutes=v!)),const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[_row('Valor de referência','R\$ ${gross.toStringAsFixed(2)}'),if(courtesy)_row('Desconto de cortesia','- R\$ ${gross.toStringAsFixed(2)}'),const Divider(),_row('Total',courtesy?'R\$ 0,00':'R\$ ${gross.toStringAsFixed(2)}',bold:true)]))),if(courtesy)Padding(padding:const EdgeInsets.only(top:12),child:Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(borderRadius:BorderRadius.circular(14),color:Theme.of(context).colorScheme.primaryContainer),child:const Text('🎉 Esta será sua primeira recarga. O valor será registrado como cortesia e o total a pagar será R\$ 0,00.'))),const SizedBox(height:24),FilledButton(onPressed:()=>_confirm(context,courtesy),child:const Padding(padding:EdgeInsets.all(14),child:Text('Confirmar reserva')))]));}
 Widget _row(String a,String b,{bool bold=false})=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(children:[Expanded(child:Text(a,style:TextStyle(fontWeight:bold?FontWeight.bold:null))),Text(b,style:TextStyle(fontWeight:bold?FontWeight.bold:null,fontSize:bold?17:14))]));
 Future<void> _confirm(BuildContext context,bool courtesy) async {if(courtesy)await context.read<AppState>().markCourtesyUsed();if(context.mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Reserva criada'),content:Text(courtesy?'Sua primeira recarga foi registrada como cortesia.':'Sua reserva foi registrada.'),actions:[TextButton(onPressed:()=>Navigator.of(context).popUntil((r)=>r.isFirst),child:const Text('Concluir'))]));}
}
